// PokePat mod platinum-level-caps: battle Exp. stops one point before the level after the cap.
if (data->battleSys->levelCap != 0 && data->battleSys->levelCap < MAX_POKEMON_LEVEL) {
    u32 oldExp = newExp - totalExp;
    u32 capExp = Pokemon_GetSpeciesBaseExpAt(Pokemon_GetValue(mon, MON_DATA_SPECIES, NULL), data->battleSys->levelCap + 1) - 1;

    if (capExp < oldExp) {
        capExp = oldExp;
    }

    if (newExp > capExp) {
        newExp = capExp;
        totalExp = newExp - oldExp;
    }
}
